#include <type_traits>
struct Start {};
struct Finish {};
using Event = std::variant<Start, Finish>;
int main() {
    Event event = Start{};
    std::visit(
        [](const auto &item) {
            using T = std::decay_t<decltype(item)>;
            if constexpr (std::is_same_v<T, Start>) {
                std::cout << "start\n";
            } else {
                std::cout << "finish\n";
            }
        },
        event);
}

